import{_ as o,o as r,c as a,O as t}from"./chunks/framework.db831a78.js";const g=JSON.parse('{"title":"JVM","description":"","frontmatter":{},"headers":[],"relativePath":"interview/后端/Java/02-JVM.md","filePath":"interview/后端/Java/02-JVM.md","lastUpdated":1788851914000}'),s={name:"interview/后端/Java/02-JVM.md"};function n(c,e,i,d,l,p){return r(),a("div",null,e[0]||(e[0]=[t('<h1 id="jvm" tabindex="-1">JVM <a class="header-anchor" href="#jvm" aria-label="Permalink to &quot;JVM&quot;">​</a></h1><blockquote><p><strong>怎么用这份笔记</strong></p><ul><li>分级：<code>★★★ 必须吃透</code> / <code>★★☆ 了解即可（记结论就行）</code> / <code>★☆☆ 可以跳过（一句话看一眼）</code></li><li>【简历亮点，高频追问】：简历里写过的技术，面试官会顺着往下挖，这段必须能展开讲</li><li>每个考点固定三段：<strong>通俗理解 → 我的项目关联 → 面试答题话术</strong></li><li>「我的项目关联」里的坑分两种，别搞混： <ul><li>写**「线上」**= 真实发生过的问题，可以直接讲现象和修复</li><li>写**「通用坑」<strong>= 经典坑 / 资料里学到的，我们项目没实际踩到，面试时</strong>别说成自己踩过**</li></ul></li></ul></blockquote><hr><h2 id="_1-jvm-内存区域划分-哪些会-oom-★★★" tabindex="-1">1. JVM 内存区域划分，哪些会 OOM ★★★ <a class="header-anchor" href="#_1-jvm-内存区域划分-哪些会-oom-★★★" aria-label="Permalink to &quot;1. JVM 内存区域划分，哪些会 OOM ★★★&quot;">​</a></h2><p><strong>通俗理解</strong> JVM 把内存分成几块：跟线程一对一的是「线程私有」的——程序计数器（记执行到哪行，唯一不会 OOM）、虚拟机栈（方法调用的栈帧，递归太深会 StackOverflowError）、本地方法栈；所有线程共用的是「线程共享」的——堆（放对象，GC 主战场）、方法区 / 元空间（放类信息、静态变量、常量）。另外还有一块堆外的直接内存。</p><p><strong>我的项目关联</strong> 网关、互联互通、对账这几个服务都跑在 Docker 容器里，容器内存有限，所以我最关心两件事：堆别撑爆（堆 OOM），元空间别无限涨（用 CGLIB 动态代理、频繁热部署会产生很多类）。我们启动参数里堆是 <code>-Xms</code>/<code>-Xmx</code> 设成相等，元空间也给了上限，就是防容器被拖垮。</p><p><strong>面试答题话术</strong> 「分线程私有和共享两类。私有的有程序计数器、虚拟机栈、本地方法栈；共享的是堆、方法区（8 之后叫元空间）。会 OOM 的是堆、元空间、直接内存，栈是 StackOverflowError 为主。放容器里跑的话，堆和元空间我都会显式给上限，不然元空间默认能吃满物理内存，把容器搞挂。」</p><hr><h2 id="_2-对象创建过程、内存布局、对象头-★★☆" tabindex="-1">2. 对象创建过程、内存布局、对象头 ★★☆ <a class="header-anchor" href="#_2-对象创建过程、内存布局、对象头-★★☆" aria-label="Permalink to &quot;2. 对象创建过程、内存布局、对象头 ★★☆&quot;">​</a></h2><p><strong>通俗理解</strong><code>new</code> 一个对象大概五步：先检查类加载了没 → 在堆里分一块内存 → 内存清零（保证字段有默认值）→ 设对象头 → 执行构造器。对象在内存里分三块：对象头（Mark Word 存 hashCode、GC 年龄、锁状态，加类型指针）、实例数据（字段值）、对齐填充（凑成 8 字节整数倍）。分配内存有指针碰撞和空闲列表两种，还有 TLAB 让线程先在自己的小缓冲里分，减少竞争。</p><p><strong>我的项目关联</strong> 这块主要是为了回答「HashMap 里对象多大」「锁升级」这类延伸问题。实际开发我不直接碰对象头，但知道它跟锁升级（偏向锁 → 轻量级锁 → 重量级锁）是一回事，问 synchronized 的时候会用到。</p><p><strong>面试答题话术</strong> 「对象创建是：类加载检查、分内存、清零、设对象头、执行构造器。对象头里 Mark Word 是关键，hashCode、GC 年龄、锁状态都塞在里面，会复用同一块位。分内存有指针碰撞和空闲列表，HotSpot 用 TLAB 让线程本地分配减少锁竞争。TLAB 这个点被问到我就说：它是线程私有的一小块堆，线程先在自己这块分，分不下了再走 CAS。」</p><hr><h2 id="_3-如何判断对象是垃圾-四种引用-★★★" tabindex="-1">3. 如何判断对象是垃圾；四种引用 ★★★ <a class="header-anchor" href="#_3-如何判断对象是垃圾-四种引用-★★★" aria-label="Permalink to &quot;3. 如何判断对象是垃圾；四种引用 ★★★&quot;">​</a></h2><p><strong>通俗理解</strong> 两种算法：引用计数（被引用数归零就回收，但解决不了 A 和 B 互相引用）和可达性分析（从 GC Roots 出发，能走到的就活着，走不到的才算垃圾）。HotSpot 用的是可达性分析。GC Roots 主要是栈里的局部变量、静态变量、常量、native 引用。四种引用从强到弱：强（绝不回收）、软（内存不够才回收，适合做缓存）、弱（一 GC 就回收）、虚（拿不到对象，只在回收时收个通知，NIO 清理直接内存就靠它）。</p><p><strong>我的项目关联</strong> 我们做本地缓存时逻辑上跟「软引用/弱引用」思路一致：能用 Redis 就用 Redis，本地只放短期数据。ThreadLocal 的 key 是弱引用这个点，在 Netty 里很关键——Netty 的 FastThreadLocal 就是为了替代 ThreadLocal 的性能和内存泄漏问题。这块属于理解原理，没在线上出过事。</p><p><strong>面试答题话术</strong> 「判断垃圾用可达性分析，从 GC Roots 出发走不到的才算垃圾。GC Roots 就是栈里的变量、静态变量、常量这些。四种引用：强引用不回收；软引用内存不足时才回收，适合做缓存；弱引用一 GC 就没，ThreadLocal 的 key 用的就是它；虚引用拿不到对象，只用来在回收时收通知，NIO 释放堆外内存就是这套。项目里缓存我是直接用 Redis，不靠 JVM 软引用，因为 JVM 缓存不好控容量。」</p><hr><h2 id="_4-gc-三大算法-★★★" tabindex="-1">4. GC 三大算法 ★★★ <a class="header-anchor" href="#_4-gc-三大算法-★★★" aria-label="Permalink to &quot;4. GC 三大算法 ★★★&quot;">​</a></h2><p><strong>通俗理解</strong> 标记清除：标出活的、清掉死的，简单但有内存碎片。复制：内存分两半，把活的复制到另一半，没碎片但费空间——不过新生代实际是 Eden 和两块 Survivor 8:1:1，只浪费 10%，而且新生代对象大多朝生夕死，复制成本低。标记整理：把活对象都挪到一边，没碎片但移动成本高、要 STW。所以新生代用复制、老年代用标记整理。</p><p><strong>我的项目关联</strong> 这个不用死记，记住「新生代复制、老年代整理」的取舍就行。我们服务用 G1，新生代回收就是把存活对象从 Eden 搬到 Survivor，日志里看到 Eden 被打满触发 Young GC 就是这个过程。</p><p><strong>面试答题话术</strong> 「三个算法：标记清除有碎片；复制没碎片但要浪费空间，新生代用，因为对象大多朝生夕死，复制量小，而且 8:1:1 只浪费 10%；标记整理没碎片但要移动对象、得 STW，老年代用。一句话记：新生代复制，老年代整理。」</p><hr><h2 id="_5-常见垃圾收集器-重点-g1-★★★-【简历亮点-高频追问】" tabindex="-1">5. 常见垃圾收集器（重点 G1）★★★ 【简历亮点，高频追问】 <a class="header-anchor" href="#_5-常见垃圾收集器-重点-g1-★★★-【简历亮点-高频追问】" aria-label="Permalink to &quot;5. 常见垃圾收集器（重点 G1）★★★ 【简历亮点，高频追问】&quot;">​</a></h2><p><strong>通俗理解</strong> 演进路线：Serial（单线程，小内存）→ Parallel（多线程，追求吞吐，JDK8 默认）→ CMS（并发低停顿，但有碎片、有浮动垃圾，已废弃）→ G1（把堆切成很多 Region，优先回收垃圾最多的，停顿可预测，JDK9 起默认）→ ZGC（着色指针 + 读屏障，停顿亚毫秒级，支持 TB 级堆）。现在新项目基本 G1 起步，大堆低延迟才上 ZGC。</p><p><strong>我的项目关联</strong> 我们 JDK 21，默认就是 G1，参数上配了 <code>-XX:MaxGCPauseMillis</code> 控制停顿目标。G1 的核心是 Region：它不像以前那样物理划分新生代老年代，而是把堆切成一堆小块，每次挑垃圾最多的几块回收，这也是名字 Garbage First 的由来。对账服务批次跑批时会有对象突增，我们就是靠 G1 的可预测停顿 + 监控 GC 日志来兜。</p><p><strong>面试答题话术</strong> 「现在主流是 G1，JDK9 之后默认。它的思路是把堆切成很多大小相等的 Region，回收时优先挑垃圾最多的 Region，所以叫 Garbage First，还能用 MaxGCPauseMillis 设停顿目标。CMS 追求低停顿但用标记清除，有碎片、有浮动垃圾，而且并发阶段抢 CPU，JDK9 就废弃了。ZGC 是着色指针加读屏障，大部分工作并发做，STW 极短，适合超大堆。我项目里 JDK21 默认 G1，主要调停顿目标配合 GC 日志看。」</p><hr><h2 id="_6-类加载全过程-双亲委派-★★★" tabindex="-1">6. 类加载全过程；双亲委派 ★★★ <a class="header-anchor" href="#_6-类加载全过程-双亲委派-★★★" aria-label="Permalink to &quot;6. 类加载全过程；双亲委派 ★★★&quot;">​</a></h2><p><strong>通俗理解</strong> 类加载五步：加载（读字节码、生成 Class 对象）→ 验证（保证字节码安全）→ 准备（静态变量给零值，比如 <code>static int i = 1</code> 此时 i 还是 0）→ 解析（符号引用换直接引用）→ 初始化（执行 <code>&lt;clinit&gt;</code>，真正给静态变量赋值、跑静态代码块）。双亲委派就是：要加载一个类，先让父加载器去加载，父的加载不了才自己上。好处是避免重复加载、防止自己写个假的 <code>java.lang.String</code> 把核心类替换掉。破坏它的典型场景是 JDBC 的 SPI 和 Tomcat 的类隔离。</p><p><strong>我的项目关联</strong> 实际开发不太会自己写类加载器，但有两个点面试常问：一是准备阶段和初始化阶段对静态变量的区别；二是为什么 JDBC 驱动能被加载——因为 <code>DriverManager</code> 是启动类加载器加载的，加载不到 classpath 里的驱动实现，所以用线程上下文类加载器反向去拿。SPI 这个我们在对接第三方时就靠这类机制（JDK 的 SPI、Spring 的 <code>SpringFactoriesLoader</code> 都是这个套路）。</p><p><strong>面试答题话术</strong> 「类加载五步：加载、验证、准备、解析、初始化。准备阶段只给静态变量设零值，真正赋值在初始化阶段，这是常考的点。双亲委派就是向上委托，父加载器加载不了才自己加载，目的是避免重复加载、防止核心类被篡改。破坏它的经典例子是 JDBC：DriverManager 由启动类加载器加载，但驱动实现类在 classpath 里，所以用线程上下文类加载器反向加载，这就是 SPI 机制。Spring 里加载自动配置的 SpringFactoriesLoader 也是同一个思路。」</p><hr><h2 id="_7-oom-常见场景与排查工具-jmap-jstack-jstat-★★★-【简历亮点-高频追问】" tabindex="-1">7. OOM 常见场景与排查工具（jmap / jstack / jstat）★★★ 【简历亮点，高频追问】 <a class="header-anchor" href="#_7-oom-常见场景与排查工具-jmap-jstack-jstat-★★★-【简历亮点-高频追问】" aria-label="Permalink to &quot;7. OOM 常见场景与排查工具（jmap / jstack / jstat）★★★ 【简历亮点，高频追问】&quot;">​</a></h2><p><strong>通俗理解</strong> 常见 OOM：堆溢出（对象太多/大对象，<code>Java heap space</code>）、栈溢出（递归太深，<code>StackOverflowError</code>）、元空间溢出（动态生成类太多，<code>Metaspace</code>）、GC 开销超限（<code>GC overhead limit exceeded</code>）、直接内存溢出（<code>Direct buffer memory</code>）。工具箱：jps 看进程、jstat 看 GC、jmap 导出堆快照给 MAT 分析、jstack 打线程栈查死锁和 CPU 高的线程。</p><p><strong>我的项目关联</strong> 我们线上服务开了 <code>-XX:+HeapDumpOnOutOfMemoryError</code>，真 OOM 了会自动 dump，然后我用 MAT 看谁占得最多。查 CPU 飙高是「top 找进程 → <code>top -Hp</code> 找线程 → 线程号转十六进制 → jstack 里找 nid」这套。这块属于我的运维基本功，配合监控告警用，<strong>说明一下</strong>：我们线上没有发生过严重堆 OOM，这个流程是日常排障和演练用的，不是「出过大事才学会」。</p><p><strong>面试答题话术</strong> 「排查思路先说工具：jps 找进程、jstat 看 GC 频率和堆变化、jmap 导堆快照给 MAT 找大对象、jstack 看线程栈。堆 OOM 一般是对象泄漏或者大对象，看 MAT 的支配树找谁在占；CPU 飙高是 top 找进程、top -Hp 找线程、线程号转十六进制、再去 jstack 找 nid，一般是死循环、频繁 Full GC 或者锁竞争。我们生产开了 HeapDumpOnOutOfMemoryError，真出事能留现场，平时靠监控先发现 GC 异常。」</p><hr><h2 id="_8-逃逸分析、栈上分配-★★☆" tabindex="-1">8. 逃逸分析、栈上分配 ★★☆ <a class="header-anchor" href="#_8-逃逸分析、栈上分配-★★☆" aria-label="Permalink to &quot;8. 逃逸分析、栈上分配 ★★☆&quot;">​</a></h2><p><strong>通俗理解</strong> 逃逸分析：JIT 判断一个对象会不会「跑出」方法或线程。不会跑出去的，就能做优化——栈上分配（对象随方法结束直接销毁，不进堆）、标量替换（把对象拆成基本类型）、锁消除（不会被别人共享就把 synchronized 去掉）。HotSpot 默认开，但真正生效的是标量替换，不是字面意义的栈上分配。</p><p><strong>我的项目关联</strong> 记结论就行，实践中影响很小，属于面试凑分点。真正跟性能相关的是「锁消除」，比如方法里 new 一个 StringBuilder 加 synchronized，逃逸分析会直接把锁干掉。</p><p><strong>面试答题话术</strong> 「逃逸分析是 JIT 判断对象会不会逃出方法。不逃逸的可以做栈上分配、标量替换、锁消除。默认是开的，但其实 HotSpot 没有真正的栈上分配，是靠标量替换实现的。这个点实际价值不大，知道结论就行。」</p><hr><h2 id="_9-jvm-常用调优参数-★★☆" tabindex="-1">9. JVM 常用调优参数 ★★☆ <a class="header-anchor" href="#_9-jvm-常用调优参数-★★☆" aria-label="Permalink to &quot;9. JVM 常用调优参数 ★★☆&quot;">​</a></h2><p><strong>通俗理解</strong> 堆：<code>-Xms</code>/<code>-Xmx</code>（建议设成相等，避免动态扩容抖动）、<code>-Xmn</code> 新生代；栈：<code>-Xss</code>；元空间：<code>-XX:MaxMetaspaceSize</code>；选 GC：<code>-XX:+UseG1GC</code>；停顿目标：<code>-XX:MaxGCPauseMillis</code>；日志：<code>-Xlog:gc*</code>；OOM 自动 dump：<code>-XX:+HeapDumpOnOutOfMemoryError</code>。思路是「先看监控再调」，别上来就加内存。</p><p><strong>我的项目关联</strong> 我们的服务打包成 Docker 镜像，JVM 参数统一写在启动脚本/编排里：堆固定大小、元空间上限、开 GC 日志、开 OOM dump。核心理念是容器内存就那么多，JVM 参数必须显式给，不能靠默认值——容器里 JVM 识别不到宿主内存，默认值可能超容器限额被 OOM Killer 干掉。</p><p><strong>面试答题话术</strong> 「参数就几类：堆用 Xms/Xmx，一般设成相等避免扩容抖动；栈用 Xss；元空间设 MaxMetaspaceSize；GC 用 UseG1GC；停顿目标用 MaxGCPauseMillis；再开 GC 日志和 OOM dump。调优思路是先看监控和 GC 日志，确认是内存、CPU 还是 GC 瓶颈再动手。放到容器里有个坑：JVM 默认堆是按宿主内存算的，容器里不显式设可能超限额被系统杀掉。」</p><hr><h2 id="_10-jmm-与-jvm-内存模型的区别-★★★" tabindex="-1">10. JMM 与 JVM 内存模型的区别 ★★★ <a class="header-anchor" href="#_10-jmm-与-jvm-内存模型的区别-★★★" aria-label="Permalink to &quot;10. JMM 与 JVM 内存模型的区别 ★★★&quot;">​</a></h2><p><strong>通俗理解</strong> 这是两个完全不同的东西，最容易被混淆。JVM 内存模型（运行时数据区）说的是「数据存在哪」——堆、栈、方法区。JMM（Java 内存模型）说的是「多线程怎么安全读写共享变量」——把内存抽象成主内存（共享）和每个线程的工作内存（私有副本），通过 volatile、synchronized、final 这些建立 happens-before 规则，保证可见性和有序性。</p><p><strong>我的项目关联</strong> 网关是多线程环境，Netty Worker 线程和 Kafka 消费线程都在跑，共享状态（设备会话、下发队列标志位）都必须用 volatile 或者原子类。我们踩过（通用坑级别）：一个「停止标志」没用 volatile，改了之后线程读的还是旧值，循环停不下来——这是 JMM 可见性的经典问题，解决办法就是加 volatile 或者用 AtomicBoolean。</p><p><strong>面试答题话术</strong> 「这两个别混：JVM 内存模型说的是数据放在哪，是堆栈方法区，是存储划分；JMM 是并发规范，说的是主内存和工作内存，解决多线程读写共享变量的可见性和有序性。JMM 靠 volatile、synchronized、happens-before 来立规矩。我项目里网关是多线程的，共享的开关标志一定用 volatile 或 AtomicBoolean，不然改了别的线程读不到。」</p><hr><h2 id="_11-元空间-vs-永久代、字符串常量池位置-★★☆" tabindex="-1">11. 元空间 vs 永久代、字符串常量池位置 ★★☆ <a class="header-anchor" href="#_11-元空间-vs-永久代、字符串常量池位置-★★☆" aria-label="Permalink to &quot;11. 元空间 vs 永久代、字符串常量池位置 ★★☆&quot;">​</a></h2><p><strong>通俗理解</strong> JDK8 之前方法区的实现叫永久代（在堆里，受 <code>-XX:MaxPermSize</code> 限制）；JDK8 之后换成元空间，挪到本地内存，默认没上限，得用 <code>-XX:MaxMetaspaceSize</code> 自己限。字符串常量池 JDK7 就从永久代挪到堆里了。本质是避免固定大小导致永久代 OOM。</p><p><strong>我的项目关联</strong> 不用深挖，记住「8 之后是元空间、在本地内存、要自己设上限」就够了。我们用 CGLIB 做代理的场景不少，代理类都会进元空间，所以启动参数固定给 MaxMetaspaceSize。</p><p><strong>面试答题话术</strong> 「8 之前是永久代，在堆里、有固定大小、容易 OOM；8 之后是元空间，挪到本地内存，默认没上限，得用 MaxMetaspaceSize 限。字符串常量池 7 就移到堆里了。一句话：元空间就是方法区的新实现，但换了物理位置。」</p><hr><h2 id="_12-直接内存-netty-重点-★★☆" tabindex="-1">12. 直接内存（Netty 重点）★★☆ <a class="header-anchor" href="#_12-直接内存-netty-重点-★★☆" aria-label="Permalink to &quot;12. 直接内存（Netty 重点）★★☆&quot;">​</a></h2><p><strong>通俗理解</strong> NIO 的 <code>ByteBuffer.allocateDirect</code> 分配的是堆外内存，好处是不受 GC 管、省掉了堆内堆外拷贝，做网络 IO 性能好。代价是不在堆里、不好监控，满了抛 <code>Direct buffer memory</code>，要手动设 <code>-XX:MaxDirectMemorySize</code>。释放靠虚引用 + Cleaner，等 GC 时回收。</p><p><strong>我的项目关联</strong><strong>这块跟我们网关强相关，要能讲。</strong> Netty 默认就用堆外直接内存（<code>PooledByteBufAllocator</code>）收发充电桩报文，性能好。风险也很直接：如果直接内存设得太小或者 ByteBuf 没释放，就会报 <code>Direct buffer memory</code> OOM，而且堆 dump 里看不到——因为它在堆外。所以我们的经验是：<code>-XX:MaxDirectMemorySize</code> 显式给足，Netty 的 ByteBuf 严格按引用计数 release，用 Netty 自带的内存泄漏检测（<code>-Dio.netty.leakDetection.level</code>）在测试环境先照出来。</p><p><strong>面试答题话术</strong> 「直接内存是堆外内存，NIO 用它是因为省掉一次堆内堆外拷贝，IO 性能好，Netty 默认就用这个。坑是它在堆外，GC 日志和堆 dump 都看不到，满了报 Direct buffer memory，而且默认上限等于 Xmx，容器里要显式设 MaxDirectMemorySize。释放靠 Cleaner 加虚引用，得等 GC。我们网关用 Netty，所以对 ByteBuf 的 release 和 Netty 自带的内存泄漏检测看得比较重。」</p><hr><h2 id="_13-三色标记、对象进老年代条件、stw-★★☆" tabindex="-1">13. 三色标记、对象进老年代条件、STW ★★☆ <a class="header-anchor" href="#_13-三色标记、对象进老年代条件、stw-★★☆" aria-label="Permalink to &quot;13. 三色标记、对象进老年代条件、STW ★★☆&quot;">​</a></h2><p><strong>通俗理解</strong> 三色标记是并发标记用的：白（没扫到）、灰（扫到了但子对象没扫完）、黑（子对象都扫完）。并发时用户线程还在改引用，容易「漏标」，所以 CMS 用增量更新、G1 用 SATB（原始快照）来补救。对象进老年代：年龄到阈值（默认 15）、大对象直接进、Survivor 塞不下触发动态年龄判断。STW 就是 GC 时停掉所有用户线程，任何 GC 都有 STW，只是长短不同。</p><p><strong>我的项目关联</strong> 结论够用。G1 的 SATB 我答一句就行：靠写屏障记录并发期间的引用变化，最后重新扫一遍这些，防止对象被误回收。这块属于知道结论，没在项目里深调。</p><p><strong>面试答题话术</strong> 「三色标记就是白灰黑三种状态，并发标记时会漏标，所以 CMS 用增量更新、G1 用 SATB 补救。对象进老年代主要看年龄到 15、大对象直接进、Survivor 放不下动态晋升。STW 是所有 GC 都有的，只是 ZGC 那种能压到极短，所谓低停顿就是压 STW 时间。」</p><hr><h2 id="_14-jvm-出现-oom-会导致进程挂掉吗-★★★" tabindex="-1">14. JVM 出现 OOM 会导致进程挂掉吗 ★★★ <a class="header-anchor" href="#_14-jvm-出现-oom-会导致进程挂掉吗-★★★" aria-label="Permalink to &quot;14. JVM 出现 OOM 会导致进程挂掉吗 ★★★&quot;">​</a></h2><p><strong>通俗理解</strong> 不一定，看 OOM 出在哪、有没有被捕获。堆 OOM 抛 <code>OutOfMemoryError</code>，如果没人 catch，通常只是当前那个线程挂了，JVM 本身可能还活着（但也不健康）。元空间、栈、直接内存 OOM 同理，都是抛异常。真正让进程「直接消失」的是操作系统层面的 OOM Killer，进程被 kill 掉，日志里没有 Java 异常。注意 <code>OutOfMemoryError</code> 是 <code>Throwable</code>，<code>catch(Throwable)</code> 能抓到，但抓完进程状态通常已经不可靠了。</p><p><strong>我的项目关联</strong> 实际经验是：OOM 后即使进程没死也建议尽快重启，因为内存状态已经乱了，容易连环 OOM。容器里更要注意——如果 JVM 堆超过了容器的 memory limit，是直接被 OOM Killer 杀掉，pod 直接重启，这时候要去看 dmesg 或者容器的 exit code 137，而不是 Java 日志。这个坑我们是通过给 JVM 显式设堆上限 + 容器 limit 留富余来防的。</p><p><strong>面试答题话术</strong> 「不一定。堆 OOM、元空间 OOM 都是抛 OutOfMemoryError，如果没人 catch，一般是当前线程挂，进程可能还活着，但已经不可靠了，建议尽快重启。进程直接消失一般是操作系统 OOM Killer 干的，日志里看不到 Java 异常，容器里就要看 exit code 137。所以容器部署时 JVM 堆要显式设，还得比容器 limit 小一截，给堆外内存留空间。」</p><hr><h2 id="附-一句话速记-可以跳过-★☆☆" tabindex="-1">附：一句话速记（可以跳过 ★☆☆） <a class="header-anchor" href="#附-一句话速记-可以跳过-★☆☆" aria-label="Permalink to &quot;附：一句话速记（可以跳过 ★☆☆）&quot;">​</a></h2><ul><li>Serial / ParNew / Parallel：老收集器，新项目基本不用了，知道名字和特点即可。</li><li>PermGen：JDK7 及以前的方法区实现，已废弃，现在一律说元空间。</li></ul>',75)]))}const M=o(s,[["render",n]]);export{g as __pageData,M as default};
